mapper.select:
SELECT a.id, a.check_user_id, a.status, b.task_name, b.duty_user_id, a.check_total_number, a.estimate_end_time, a.reality_end_time, a.check_complete_number, a.check_win_number, a.check_loss_number, a.abnormal_number FROM property_check_task a INNER JOIN property_check_plan b ON a.plan_id = b.id WHERE a.check_user_id=#{checkUserId}
and a.id=#{param.taskId}
and a.id in
#{item}
and a.status=#{param.status}
and b.task_name like concat ('%',#{param.keyword},'%')
and b.task_name like concat ('%',#{param.taskName},'%')
order by a.create_time desc

SELECT b.*
FROM `property_check_task_relation` a
inner join property_check_task b on a.task_id = b.id
where a.property_id = #{param.propertyId}

    AND b.create_time BETWEEN #{param.period.begin} AND #{param.period.end}


    and b.status=#{param.status}
